//! About → Credits: what Lodestar is built from, read from the embedded THIRD_PARTY_NOTICES.md
//! (generated by `tools/gen-third-party-notices.py`; one source of truth for the desktop page,
//! the controller page and the file shipped next to the program).

/// The whole notices file, as shipped.
pub const NOTICES: &str = include_str!("../../THIRD_PARTY_NOTICES.md");

/// The communities Lodestar owes the most: (who, what for, link).
pub const THANKS: &[(&str, &str, &str)] = &[
    (
        "Playnite",
        "the model for Lodestar's library, its platform list, ROM database and theme import",
        "https://playnite.link",
    ),
    ("ES-DE", "the ROM folder names Lodestar recognises", "https://es-de.org"),
    (
        "libretro / RetroArch",
        "emulator cores, the thumbnail collection and the game databases behind ROM matching",
        "https://www.libretro.com",
    ),
    ("No-Intro, Redump and GameTDB", "the game lists that let Lodestar recognise ROM files", "https://no-intro.org"),
    ("egui", "the toolkit Lodestar's windows are drawn with", "https://github.com/emilk/egui"),
    ("Rust", "the language Lodestar is written in", "https://www.rust-lang.org"),
];

/// The notices without the machine-readable Cargo.lock list at the end (for reading / copying).
pub fn readable() -> &'static str {
    match NOTICES.find("<!-- cargo-lock") {
        Some(i) => NOTICES[..i].trim_end(),
        None => NOTICES.trim_end(),
    }
}

/// The lines of the `## heading` section (up to the next `## `).
fn section<'a>(md: &'a str, heading: &str) -> Vec<&'a str> {
    let mut out = vec![];
    let mut inside = false;
    let mut fence = false;
    for l in md.lines() {
        if l.starts_with("```") {
            fence = !fence;
        }
        if !fence && l.starts_with("## ") {
            if inside {
                break;
            }
            inside = l[3..].trim() == heading;
            continue;
        }
        if inside {
            out.push(l);
        }
    }
    out
}

/// The rows of the first table of a section, header row and separator left out; cells trimmed.
pub fn table(md: &str, heading: &str) -> Vec<Vec<String>> {
    let rows: Vec<Vec<String>> = section(md, heading)
        .into_iter()
        .skip_while(|l| !l.starts_with('|'))
        .take_while(|l| l.starts_with('|'))
        .map(|l| l.trim().trim_matches('|').split(" | ").map(|c| c.trim().to_string()).collect())
        .collect();
    rows.into_iter().skip(2).collect()
}

/// `## heading` → `### licence (n)` groups → library names (`- **name** version — …`).
pub fn library_groups(md: &str, heading: &str) -> Vec<(String, Vec<String>)> {
    let mut out: Vec<(String, Vec<String>)> = vec![];
    for l in section(md, heading) {
        if let Some(h) = l.strip_prefix("### ") {
            let lic = h.rsplit_once(" (").map_or(h, |(a, _)| a);
            out.push((lic.to_string(), vec![]));
        } else if let Some(rest) = l.strip_prefix("- **")
            && let Some((name, after)) = rest.split_once("**")
            && let Some(g) = out.last_mut()
        {
            let ver = after.split_whitespace().next().unwrap_or("");
            g.1.push(format!("{name} {ver}"));
        }
    }
    out
}

/// The libraries built into the program, by licence.
pub fn built_in() -> Vec<(String, Vec<String>)> {
    library_groups(NOTICES, "Rust libraries built into Lodestar")
}

/// Text without Markdown marks: `**a**` / `` `a` `` → a.
pub fn plain(s: &str) -> String {
    s.replace("**", "").replace('`', "")
}

/// The first part of a licence cell: "MIT, Copyright (c) … (notice below). More …" → "MIT".
pub fn short(cell: &str) -> String {
    let mut end = cell.len();
    for cut in [" (", ";", ", Copyright", ". "] {
        if let Some(i) = cell.find(cut) {
            end = end.min(i);
        }
    }
    cell[..end].trim().trim_end_matches('.').to_string()
}

/// The site of a "https://…" cell, else the cell itself.
pub fn link_of(cell: &str) -> Option<&str> {
    cell.split_whitespace().find(|w| w.starts_with("https://") || w.starts_with("http://"))
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Every Cargo.lock package must be in the notices' list (with whether it is built in), so
    /// adding or updating a dependency without re-running the generator fails here.
    #[test]
    fn notices_cover_cargo_lock() {
        let lock = include_str!("../../Cargo.lock");
        let mut want = vec![];
        let mut name = None;
        for l in lock.lines() {
            if l == "[[package]]" {
                name = None;
            } else if let Some(n) = l.strip_prefix("name = ") {
                name = Some(n.trim_matches('"').to_string());
            } else if let Some(v) = l.strip_prefix("version = ")
                && let Some(n) = name.take()
                && n != env!("CARGO_PKG_NAME")
            {
                want.push(format!("{n}@{}", v.trim_matches('"')));
            }
        }
        want.sort();
        let list = &NOTICES[NOTICES.find("<!-- cargo-lock").expect("cargo-lock list")..];
        let list = &list[list.find("):").expect("list header") + 2..list.find("-->").unwrap()];
        let mut have: Vec<String> =
            list.split_whitespace().map(|m| m.split_once(':').expect("mark:name@version").1.to_string()).collect();
        have.sort();
        assert!(want.len() > 100, "parsed Cargo.lock: {}", want.len());
        let missing: Vec<_> = want.iter().filter(|w| !have.contains(w)).collect();
        let stale: Vec<_> = have.iter().filter(|h| !want.contains(h)).collect();
        assert!(
            missing.is_empty() && stale.is_empty(),
            "THIRD_PARTY_NOTICES.md is out of date (run `python3 -I tools/gen-third-party-notices.py`): \
             missing {missing:?}, no longer used {stale:?}"
        );
    }

    #[test]
    fn notices_name_what_the_release_needs() {
        for must in [
            "Copyright (c) 2020 Josef Nemec",
            "Bitstream Vera",
            "Arev Fonts Copyright",
            "System.dat",
            "SIL Open Font License",
            "UBUNTU FONT LICENCE",
            "Apache License",
            "Mozilla Public License Version 2.0",
            "SDL_GameControllerDB",
            "public domain",
            "### MIT",
        ] {
            assert!(NOTICES.contains(must), "{must}");
        }
        let groups = built_in();
        let n: usize = groups.iter().map(|g| g.1.len()).sum();
        assert!(n > 100, "{n} libraries");
        let all: Vec<&String> = groups.iter().flat_map(|g| &g.1).collect();
        for c in ["egui ", "rusqlite ", "ureq ", "gilrs ", "resvg "] {
            assert!(all.iter().any(|l| l.starts_with(c)), "{c}");
        }
        assert!(groups.iter().any(|g| g.0 == "MIT OR Apache-2.0"));
        // No copyleft-only library in the program (a GPL alternative is fine, it isn't taken).
        for (lic, libs) in &groups {
            assert!(!lic.contains("GPL") || lic.contains(" OR "), "{lic}: {libs:?}");
        }
        assert!(!readable().contains("cargo-lock"));
    }

    #[test]
    fn tables_and_links() {
        let services = table(NOTICES, "Online services");
        assert!(services.len() >= 10, "{services:?}");
        assert!(services.iter().all(|r| r.len() == 3 && link_of(&r[2]).is_some()), "{services:?}");
        for s in ["SteamGridDB", "IGDB (Twitch)", "GameTDB", "libretro-thumbnails", "Wikipedia"] {
            assert!(services.iter().any(|r| r[0] == s), "{s}");
        }
        let fonts = table(NOTICES, "Fonts built into Lodestar");
        assert!(fonts.iter().any(|r| r[0].starts_with("LodestarSymbols")));
        assert!(!table(NOTICES, "Data built into Lodestar").is_empty());
        assert_eq!(plain("**a** `b`"), "a b");
        assert_eq!(short("MIT, Copyright (c) 2020 Josef Nemec (notice below)"), "MIT");
        assert_eq!(short("Playnite: MIT (notice below). The DAT groups …"), "Playnite: MIT");
        assert_eq!(short("Facts only, no files copied. Playnite: MIT"), "Facts only, no files copied");
        assert_eq!(short("Lodestar's own"), "Lodestar's own");
        assert_eq!(link_of("see https://x.org now"), Some("https://x.org"));
        // A heading inside a licence text's code block doesn't end a section.
        let md = "## A\n| h | i |\n| --- | --- |\n| 1 | 2 |\n```\n## B\n```\n## C\n";
        assert_eq!(table(md, "A"), vec![vec!["1".to_string(), "2".to_string()]]);
        assert!(table(md, "B").is_empty());
    }
}
